<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {api,ApiError} from '../lib/api';
const props=defineProps<{campaignId:string}>(),emit=defineEmits<{refresh:[];attention:[count:number]}>();
const impulse=ref<Record<string,boolean>>({}),offers=ref<any[]>([]),loadingError=ref(''),error=ref(''),notice=ref(''),busy=ref(false),pending=ref<any>(null);
let alive=true,loading=false,timer:ReturnType<typeof setInterval>|undefined;
watch(offers,list=>emit('attention',list.length),{immediate:true});
async function load(){if(!alive||loading||document.visibilityState==='hidden')return;loading=true;try{const result=await api<any>(`/api/campaigns/${props.campaignId}/occult-consents`);if(alive){offers.value=result.offers??[];loadingError.value='';}}catch{if(alive)loadingError.value='Les propositions privées ne sont pas à jour.';}finally{loading=false;}}
onMounted(()=>{void load();timer=setInterval(()=>void load(),3000);});onUnmounted(()=>{alive=false;clearInterval(timer);});
async function accept(offer:any,active=false){if(busy.value||pending.value)return;pending.value={requestId:crypto.randomUUID(),action:offer.type==='decree'?'resist-decree':offer.type==='defense'?'defend':'consent',sourceEventId:offer.sourceEventId,actorId:offer.actorId,version:offer.version,offerId:offer.offerId,...(offer.type==='defense'?{active,defenseKind:offer.defenseKind,contextConfirmed:true,pursuesImpulse:impulse.value[offer.sourceEventId+offer.actorId]===true}:offer.type==='decree'?{effectId:offer.effectId,violationConfirmed:true}:{})};await retry();}
async function retry(){if(busy.value||!pending.value)return;busy.value=true;error.value='';try{await api(`/api/campaigns/${props.campaignId}/occult-resolutions`,{method:'POST',body:JSON.stringify(pending.value)});pending.value=null;notice.value='Choix transmis au MJ.';await load();emit('refresh');}catch(cause){error.value=cause instanceof ApiError?'Cette proposition a changé. Actualise avant de l’accepter.':'Accord non confirmé. Réessaie le même envoi.';if(cause instanceof ApiError&&cause.status<500){pending.value=null;await load();}}finally{busy.value=false;}}
</script>
<template>
<section v-if="offers.length||loadingError||error||notice" class="occult-consent" aria-label="Effets alliés proposés">
 <p v-if="loadingError" role="status">{{loadingError}}</p><p v-if="error" role="alert">{{error}} <button v-if="pending" :disabled="busy" @click="retry">Réessayer cet accord</button></p><p v-if="notice" role="status">{{notice}} <button class="dismiss" @click="notice=''">Fermer</button></p>
 <article v-for="offer in offers" :key="offer.sourceEventId+offer.actorId"><div><strong>{{offer.sourceName}} → {{offer.characterName}}</strong><p>{{offer.note}}</p><label v-if="offer.type==='defense'&&offer.impulse"><input v-model="impulse[offer.sourceEventId+offer.actorId]" type="checkbox" /> Cette défense poursuit mon impulsion : {{offer.impulse}}</label><p v-if="offer.type==='defense'">Défense {{offer.defenseKind==='physical'?'physique':'occulte'}} retenue par le MJ.</p></div><button v-if="offer.type==='decree'" :disabled="busy||!!pending||!!loadingError" @click="accept(offer)">Tenter de violer l’interdit · 0 PA</button><div v-else-if="offer.type==='defense'" class="defense-actions"><button :disabled="busy||!!pending||!!loadingError" @click="accept(offer,false)">Défense passive</button><button :disabled="busy||!!pending||!!loadingError||offer.pa<1" @click="accept(offer,true)">Défense active · 1 PA</button></div><button v-else :disabled="busy||!!pending||!!loadingError" @click="accept(offer)">Accepter cet effet</button></article>
</section>
</template>
<style scoped>
.occult-consent{padding:10px 12px;margin:12px 0;border:1px solid #46636c;border-radius:8px;background:#102629;min-width:0}.occult-consent article{display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0}.occult-consent article+article{border-top:1px solid #46636c;padding-top:8px;margin-top:8px}.occult-consent .defense-actions{display:flex;flex-wrap:wrap;gap:6px}.occult-consent article div{min-width:0;overflow-wrap:anywhere}.occult-consent p{margin:5px 0;line-height:1.4}.occult-consent button{min-height:44px;padding:8px 12px;border:1px solid #64868a;border-radius:6px;background:#163c40;color:#e8f9fb;cursor:pointer;flex-shrink:0}.occult-consent button:disabled{opacity:.5;cursor:default}.occult-consent .dismiss{min-height:32px;padding:3px 8px;margin-left:8px;background:transparent}@media(max-width:500px){.occult-consent article{display:block}.occult-consent article button{margin-top:6px;max-width:100%}}
</style>
